  // Rule 1, people: rescue teams go to the three districts with the most people trapped,
  // medical teams to the two with the most people critically hurt
  const ids = Object.keys(view.districts)
  const byTrapped = [...ids].sort((a, b) => view.districts[b].trapped - view.districts[a].trapped)
  const byCritical = [...ids].sort((a, b) => view.districts[b].critical - view.districts[a].critical)
  let n = 0, m = 0
  for (const team of view.teams) {
    if (team.at !== 'depot' || team.busy) continue
    if (team.kind === 'rescue') act.move(team.id, byTrapped[n++ % 3])
    if (team.kind === 'medical') act.move(team.id, byCritical[m++ % 2])
  }
`,Rn=`
